import { describe, expect, it } from 'vitest';
import { decodeThreadRoute } from '../../src/gmail/thread-route';

// Public user-reported pair; not generated by our implementation.
const token = 'FMfcgxmZVPbZvwJWCvBMvjxglSMPvsvW';
describe('restricted opaque Gmail route decoding', () => {
  it('decodes the public thread-route vector without numeric precision loss', () => {
    expect(decodeThreadRoute(token)).toEqual({
      permanentId: 'thread-f:1598813675238698821',
      legacyId: '1630209116a3af45',
    });
  });
  it.each([
    '',
    'FMfcgzQXymQ',
    `B${token}`,
    `${token}=`,
    `${token}/`,
    `${token}0`,
    'B'.repeat(1000),
  ])('rejects invalid or noncanonical routes: %s', (value) => {
    expect(decodeThreadRoute(value)).toBeNull();
  });
  it('rejects the InboxSDK draft URL vector rather than confusing a draft with a thread', () => {
    expect(
      decodeThreadRoute(
        'CqMvqmRLbRhtqczNhFhkDQPRFTQBHmDpFpKtPVWGdZHFgscZcWpMKGJpSjgpgpvdSbRMRTSpSxB',
      ),
    ).toBeNull();
  });
});
